prologue:
static MOD_UNUSED AmodMenuItem menu_item(const char* menu, const char* item) {
    return API->objectsMenu != 0 ? API->objectsMenu->FindItem(SELF, menu, item) : 0;
}

static MOD_UNUSED int menu_has(const char* menu, const char* item, const char* key) {
    AmodMenuItem found = menu_item(menu, item);
    return found != 0 && API->objectsMenu->HasProperty(SELF, found, key) != 0;
}

static MOD_UNUSED int menu_set_text(const char* menu, const char* item, const char* key, const char* text) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_STRING;
    value.text = text;
    return API->objectsMenu->SetProperty(SELF, found, key, &value);
}

static MOD_UNUSED int menu_set_number(const char* menu, const char* item, const char* key, int number) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_INT;
    value.integer = number;
    return API->objectsMenu->SetProperty(SELF, found, key, &value);
}

static MOD_UNUSED int menu_set_floats(const char* menu, const char* item, const char* key,
                                      int count, float a, float b, float c, float d) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_FLOAT;
    value.count = (uint32_t)count;
    value.numbers[0] = a;
    value.numbers[1] = b;
    value.numbers[2] = c;
    value.numbers[3] = d;
    return API->objectsMenu->SetProperty(SELF, found, key, &value);
}

static MOD_UNUSED int menu_text_is(const char* menu, const char* item, const char* key, const char* text) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0;
    memset(&value, 0, sizeof value);
    if (API->objectsMenu->GetProperty(SELF, found, key, &value) == 0) return 0;
    return value.kind == AMOD_VALUE_STRING && value.text != 0 && strcmp(value.text, text) == 0;
}

/* Property as a number: bool and int live in integer, a float comes as the first number */
static MOD_UNUSED float menu_number(const char* menu, const char* item, const char* key) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0.0f;
    memset(&value, 0, sizeof value);
    if (API->objectsMenu->GetProperty(SELF, found, key, &value) == 0) return 0.0f;
    if (value.kind == AMOD_VALUE_FLOAT) return value.numbers[0];
    return (float)value.integer;
}

static MOD_UNUSED int menu_item_at_is(const char* menu, int index, const char* item) {
    AmodMenuItem found;
    const char* id;
    if (API->objectsMenu == 0) return 0;
    found = API->objectsMenu->GetItemAt(SELF, menu, index);
    if (found == 0) return 0;
    id = API->objectsMenu->GetItemId(SELF, found);
    return id != 0 && strcmp(id, item) == 0;
}

static MOD_UNUSED int menu_set_text_at(const char* menu, int index, const char* key, const char* text) {
    AmodValue value;
    AmodMenuItem found;
    if (API->objectsMenu == 0) return 0;
    found = API->objectsMenu->GetItemAt(SELF, menu, index);
    if (found == 0) return 0;
    memset(&value, 0, sizeof value);
    value.kind = AMOD_VALUE_STRING;
    value.text = text;
    return API->objectsMenu->SetProperty(SELF, found, key, &value);
}

/* Property as text; an empty answer when there is no such item or the property is a number */
static MOD_UNUSED const char* menu_text(const char* menu, const char* item, const char* key) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return "";
    memset(&value, 0, sizeof value);
    if (API->objectsMenu->GetProperty(SELF, found, key, &value) == 0) return "";
    return value.kind == AMOD_VALUE_STRING && value.text != 0 ? value.text : "";
}

/* One number of a property that holds several, such as $pos or $font_color */
static MOD_UNUSED float menu_float(const char* menu, const char* item, const char* key, int at) {
    AmodValue value;
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0 || at < 0 || at >= 4) return 0.0f;
    memset(&value, 0, sizeof value);
    if (API->objectsMenu->GetProperty(SELF, found, key, &value) == 0) return 0.0f;
    if (value.kind != AMOD_VALUE_FLOAT) return at == 0 ? (float)value.integer : 0.0f;
    return at < (int)value.count ? value.numbers[at] : 0.0f;
}

/* The id of the item standing at this place in the menu */
static MOD_UNUSED const char* menu_id_at(const char* menu, int index) {
    AmodMenuItem found;
    const char* id;
    if (API->objectsMenu == 0) return "";
    found = API->objectsMenu->GetItemAt(SELF, menu, index);
    if (found == 0) return "";
    id = API->objectsMenu->GetItemId(SELF, found);
    return id != 0 ? id : "";
}

/* Does the menu hold such an item at all */
static MOD_UNUSED int menu_exists(const char* menu, const char* item) {
    return menu_item(menu, item) != 0;
}

/* Properties of an item by number rather than by name: for a sheet that walks them in a loop */
static MOD_UNUSED int menu_property_count(const char* menu, const char* item) {
    AmodMenuItem found = menu_item(menu, item);
    return found != 0 ? API->objectsMenu->PropertyCount(SELF, found) : 0;
}

static MOD_UNUSED const char* menu_property_name(const char* menu, const char* item, int index) {
    AmodMenuItem found = menu_item(menu, item);
    const char* name = found != 0 ? API->objectsMenu->PropertyNameAt(SELF, found, index) : 0;
    return name != 0 ? name : "";
}

/* The element inside the game, as an address. Answered only for the build the API knows,
   and it is what reading memory and hanging data on the object are given */
static MOD_UNUSED uintptr_t menu_item_address(const char* menu, const char* item) {
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0) return 0;
    return (uintptr_t)API->objectsMenu->GetRawPointer(SELF, found, AMOD_GAME_BUILD_AZANGARA_10);
}

/* A table of the menu: the script builds its lines, and a mod fills them. Line and column are
   counted from zero, and an empty text clears the cell */
static MOD_UNUSED int menu_table_lines(const char* menu, const char* item) {
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0 || API->objectsMenu->TableLineCount == 0) return 0;
    return API->objectsMenu->TableLineCount(SELF, found);
}

static MOD_UNUSED void menu_table_cell(const char* menu, const char* item, int column, int line,
                                       const char* text) {
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0 || API->objectsMenu->SetTableCell == 0) return;
    API->objectsMenu->SetTableCell(SELF, found, column, line, text);
}

static MOD_UNUSED void menu_table_dots(const char* menu, const char* item, int line, int dots) {
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0 || API->objectsMenu->SetTableLineDots == 0) return;
    API->objectsMenu->SetTableLineDots(SELF, found, line, dots);
}

/* Colour and scale of one line; the table's own are used for whatever is left out */
static MOD_UNUSED void menu_table_style(const char* menu, const char* item, int line,
                                        float r, float g, float b, float a, float scale) {
    const float colour[4] = { r, g, b, a };
    const float size[2] = { scale, scale };
    AmodMenuItem found = menu_item(menu, item);
    if (found == 0 || API->objectsMenu->SetTableLineStyle == 0) return;
    API->objectsMenu->SetTableLineStyle(SELF, found, line, colour, size);
}
